begin
                 Print(7,'');
                 if at(26,63) then Print(15,'            길의 마지막');
                 if at(22,15) then Print(15,'     (12,15) 로 공간이동 하시오');
                 if at(11,14) then Print(15,'     (13,7) 로 공간이동 하시오');
