begin
             Clear;
             if (on(10,24)) and (party.etc[35] and bit1 = 0) then begin
                findgold(5000);
                party.etc[35] := party.etc[35] or bit1;
             end;
             if (on(12,26)) and (party.etc[35] and bit2 = 0) then begin
                findgold(5000);
                party.etc[35] := party.etc[35] or bit2;
             end;
             if (on(15,25)) and (party.etc[35] and bit3 = 0) then begin
                findgold(5000);
                party.etc[35] := party.etc[35] or bit3;
             end;
             if (on(16,23)) and (party.etc[35] and bit4 = 0) then begin
                findgold(5000);
                party.etc[35] := party.etc[35] or bit4;
             end;
             if (on(18,27)) and (party.etc[35] and bit5 = 0) then begin
                findgold(5000);
                party.etc[35] := party.etc[35] or bit5;
             end;
             if (y=10) and (party.etc[15]<5) then begin
                Message(13,'알수없는 힘이 당신을 배척합니다.');
                inc(y);
                scroll(TRUE);
             end;
             if y = 5 then
             if wantenter('SWAMP GATE') then begin
                face := 1;
                for i := 4 downto 0 do begin
                   delay(1000);
                   putimage(100,20*(i+1),font^[44],copyput);
                   if i > 0 then begin
                      PutImage(100,20*i,chara^[face+28],andPut);
                      PutImage(100,20*i,chara^[face],orPut);
                   end;
                end;
                if party.etc[35] and bit6 = 0 then begin
                   Print(15,' SWAMP GATE 로 들어가고 있는 당신에게  허공');
                   Print(15,'에서 갑자가 누군가가 말을 꺼낸다');
                   PressAnyKey;
                   cPrint(7,11,' 나는 LORE 성의 성주 ','Lord Ahn',' 이오.');
                   Print(7,' 역시 내가 예상한 대로 당신들은 훌륭한 용사');
                   Print(7,'로 성장해 나가고 있소. 여태까지는 모험이 순');
                   Print(7,'조롭게 진행 되었지만 이제부터는 완전한 적들');
                   Print(7,'의 소굴이오. 그래서 나도 직접적인 도움은 못');
                   Print(7,'주더라도 여러가지 조언을 해주겠소.');
                   PressAnyKey;
                   Print(7,' 당신들은 식량을 많이 가지고 있소?  이 식량');
                   Print(7,'은 당신들을 회복시키기  위해  필요한 것이니');
                   Print(7,'절대 바닥나게 해서는 안되오. 왜냐하면 이 이');
                   Print(7,'후에 전개되는 모험에서는 식량을 파는곳이 거');
                   Print(7,'의 없다고 생각해도 될만큼 식량이 귀중하므로');
                   Print(7,'낭패를 보는일이 없도록 하시오.');
                   PressAnyKey;
                   Print(7,' SWAMP의 대륙에서의 할일을 요약하면 이렇소.');
                   Print(7,' 스왐프 게이트와 통하는 SWAMP KEEP에는 많은');
                   Print(7,'강한 괴물들이 버티고 있소. 하지만 이전에 그');
                   Print(7,'대륙에 있는 2 개의 동굴 요새를 점령한뒤에야');
                   Print(7,'SWAMP KEEP의 중앙에 있는 라바 게이트를 작동');
                   Print(7,'시킬수 있을 것이오. 그곳의 괴물들은 매우 힘');
                   Print(7,'든 상대일 것이오. 하지만  당신들의 능력이라');
                   Print(7,'면 충분히 가능할 것이오. 나는 당신들이 라바');
                   Print(7,'게이트를 통과하려 할때 다시 조언을 해주겠소.');
                   Print(7,' 그때까지 건투를 비는 바이오.');
                   talk('');
                   party.etc[35] := party.etc[35] or bit6;
                end;
                with party do begin
                   xaxis := 81; yaxis := 95; map := 13;
                end;
                load;
                scroll(TRUE);
             end
             else begin
                inc(y); scroll(TRUE);
             end;
             if y = 46 then begin
                if wantexit then begin
                   with party do begin
                      xaxis := 32; yaxis := 82; map := 2;
                   end;
                   load;
                end
                else begin
                   dec(y); scroll(TRUE);
                end;
             end;
          end

begin
              Clear;
              if y = 71 then
              if wantexit then begin
                 with party do begin
                    xaxis := 82; yaxis := 48; map := 2;
                 end;
                 load; scroll(TRUE);
              end
              else begin
                 dec(y); scroll(TRUE);
              end;
              if (y=48) and ((x in [10,11]) or (x in [40,41])) then
              if (party.etc[36] and bit2 = 0) then begin
                 if party.etc[36] and bit1 = 0 then begin
                    party.etc[36] := party.etc[36] or bit1;
                    findgold(6000);
                 end
                 else begin
                    party.etc[36] := party.etc[36] or bit2;
                    findgold(4000);
                 end;
                 map[x,48] := 44;
                 map[x,47] := 44;
                 Silent_Scroll;
              end;
              if (on(14,7)) and (party.etc[36] and bit3 = 0) then begin
                 Print(15,'당신은 황금의 방패를 발견했다.');
                 PressAnyKey;
                 Print(11,'누가 이 황금의 방패를 장착 하겠습니까 ?');
                 k := choosewhom(FALSE);
                 if k = 0 then begin
                    asyouwish;
                    exit;
                 end;
                 with player[k] do begin
                    shield := 5;
                    shi_power := 5;
                    ac := shi_power + arm_power;
                    if class = 1 then inc(ac);
                    if ac > 10 then ac := 10;
                    message(15,name+'가 황금의 방패를 장착했다.');
                 end;
                 Display_Condition;
                 party.etc[36] := party.etc[36] or bit3;
              end;
              if (on(45,19)) and (party.etc[36] and bit4 = 0) then begin
                 Print(15,'당신은 황금의 갑옷을 발견했다.');
                 PressAnyKey;
                 Print(11,'누가 이 황금의 갑옷을 장착 하겠습니까 ?');
                 k := choosewhom(FALSE);
                 if k = 0 then begin
                    asyouwish;
                    exit;
                 end;
                 with player[k] do begin
                    armor := 5;
                    arm_power := 6;
                    ac := shi_power + arm_power;
                    if class = 1 then inc(ac);
                    if ac > 10 then ac := 10;
                    message(15,name+'가 황금의 갑옷을 장착했다.');
                 end;
                 Display_Condition;
                 party.etc[36] := party.etc[36] or bit4;
              end;
              if (y=27) and (party.etc[14]=4) then begin
                 Print(11,'당신은 ArchiGagoyle과 두마리의 Zombie를 발견했다.');
                 PressAnyKey;
                 enemynumber := 3;
                 for i := 1 to 2 do begin
                    joinenemy(i,36);
                    enemy[i].name := 'Zombie';
                 end;
                 joinenemy(3,42);
                 enemy[3].name := 'ArchiGagoyle';
                 Displayenemies(TRUE);
                 BattleMode(FALSE);
                 if party.etc[6] = 255 then exit;
                 if (party.etc[6]=0) or (enemy[3].hp<=0) then begin
                    Clear;
                    Print(15,'당신은 ArchiGagoyle을 물리쳤다.');
                    PressAnyKey;
                    inc(party.etc[14]);
                 end;    
              end;
           end

begin
      if at(12,11) or at(15,12) or at(12,15) then train_center;
      if at(40,37) or at(37,39) or at(41,41) then grocery;
      if at(37,10) or at(40,12) or at(41,15) then weapon_shop;
      if at(9,39) or at(12,41) or at(16,40) then hospital;
      if at(24,38) then
         talk(' EVIL SEAL 의 어디엔가에 ''황금의 봉인''이 숨겨져 있다더군요.');
      if at(23,12) then
         talk(' 황금의 갑옷이 QUAKE 동굴 안에 숨겨져있다는 소문이 떠돌고 있습니다.');
      if at(28,18) then begin
         Print(7,' VALIANT PEOPLES 성은 Necromancer에 대한 강');
         Print(7,'한저항 때문에  그에 의해 쑥밭이 되어 버렸습');
         Print(7,'니다.');
         PressAnyKey;
      end;
      if at(30,31) then begin
         Print(7,' VALIANT PEOPLES 최대의 사냥꾼인 Rigel은 성');
         Print(7,'을파괴시킨 적들을 물리치기 위해서 EVIL SEAL');
         Print(7,'로 들어갔습니다.');
         PressAnyKey;
      end;
      if at(34,38) then
         talk('위쪽에는 SWAMP 대륙으로 통하는 문이 있지만 아무도 접근 할 수가 없습니다.');
      if at(38,14) then
         talk('QUAKE속에는 많은 비밀문이 있다고 들었습니다.');
      if at(15,42) then
         talk('WATER FIELD 로 통하는 문에는 세마리의 Wivern이 지키고 있습니다.');
      if at(26,7) then
         talk('SWAMP 대륙으로 통하는 문에는 고르곤 세자매가 살고 있소.');
      if at(34,24) or at(37,24) or at(41,24) or at(35,27) or at(38,27) or at(41,27) then
      if party.etc[14] = 0 then talk('우리 성주님을 만나보십시오.')
      else talk('당신의 성공을 빌겠습니다.');
      if at(42,25) then
      case party.etc[14] of
         0 : begin
          Print(7,' 당신을 만나게되어 영광이오.');
          Print(7,' 나는 LORE 대륙에서의 당신의 공훈을 높이 평');
          Print(7,'가하며, 또한 LAST DITCH성을 구제하것에 대해');
          Print(7,'서도 감사를 표하오.  LAST DITCH 성의 쌍둥이');
          cPrint(7,11,'성인 ''','VALIANT PEOPLES','''는 Necromancer에 대한');
          Print(7,'강한 저항 때문에 그에 의해서  처참히 파괴되');
          Print(7,'었소.  그런후에 그는 ''VALIANT PEOPLES''의 지');
          cPrint(7,11,'하에다가 ','EVIL SEAL','이라는 동굴을 구축하였소.');
          Print(7,'그리고 그는 EVIL SEAL의 어디엔가에  이 대륙');
          Print(7,'의 운명을 담고 있는  황금의 봉인을 숨겨놓았');
          Print(7,'소. 만약 그 봉인이 풀어진다면, 이 대륙은 봉');
          Print(7,'인 속에서 나타난 괴물들에 의해서 황폐화  될');
          Print(7,'것이오.');
          cPrint(7,11,' 한시바삐 EVIL SEAL 로 가시오, 그리고 ''','황금','');
          cPrint(7,11,'','의 봉인','''을 찾으시오.');
          talk('');
          inc(party.etc[14]);
             end;
         1 : begin
          cPrint(7,11,' VALIANT PEOPLES에 있는 EVIL SEAL로 가서 ','황','');
          cPrint(7,11,'','금의 봉인','을 찾아오시오.');
          Print(7,' 지금 지체할 시간이 없소.');
          PressAnyKey;
             end;
         2 : begin
          Print(15,' 오, 당신은 황금의 봉인을 찾았군요 !');
          Print(15,' [ EXP + 10000 ]');
          for i := 1 to 6 do if player[i].name <> '' then
          player[i].experience := player[i].experience + 10000;
          PressAnyKey;
          inc(party.etc[14]);
             end;
         3 : begin
          Print(7,' 그러나, 이 대륙에는 아직 위험한 장소가  많');
          Print(7,'이 있소.');
          cPrint(7,11,' 여기로부터 북동쪽에 ''','QUAKE',''' 라고 불리는 동');
          Print(7,'굴이있소. 만약 QUAKE 마저 무너뜨리면, 이 대');
          Print(7,'륙은 다시 평화롭게 될것이오.');
          cPrint(7,11,' ','QUAKE',' 로 가서 보스인 ArchiGagoyle과 Zombie');
          Print(7,'들을 물리쳐 주십시오.');
          PressAnyKey;
          inc(party.etc[14]);
             end;
         4 : begin
          cPrint(7,11,'QUAKE의 ','ArchiGagoyle','을 물리치십시오.');
          PressAnyKey;
             end;
         5 : begin
          Print(7,'당신들은 위대한 영웅임에 틀림없군요.');
          Print(11,'[ EXP + 40000 ]');
          Print(7,'');
          cPrint(7,11,' 여기에 ','Water Key','가 있소.');
          cPrint(7,11,' 이 열쇠는 ','WATER FIELD','의 문을 열것이오.');
          for i := 1 to 6 do if player[i].name <> '' then
             player[i].experience := player[i].experience + 40000;
          PressAnyKey;
          inc(party.etc[14]);
             end;
         6 : begin
          cPrint(7,11,'WIVERN 동굴의 ','WATER FIELD의 문','을 통하여 다음 대륙으로 가십시오.');
          PressAnyKey;
             end;
      end;
         end
